let palette = ['#ca2020', '#ffba08', '#2d4fb6', '#e2e3e4'];
let grid = [];
let gridResolution = 10;
let bgColor = '#232323';

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	createGrid();

	background(bgColor);

	drawConnections();

	noStroke();
	for (let row of grid) {
		for (let cell of row) {
			let col = palette[cell.colorIndex];
			noStroke();
			fill(col);
			circle(cell.x, cell.y, cell.size);

			fill(random(palette));
			circle(cell.x, cell.y, cell.size * random(0.2, 0.4));
		}
	}
}

function drawAetherLink(x1, y1, d1, x2, y2, d2, distance) {
	let r = distance / 2;

	let r1 = d1 / 2;
	let r2 = d2 / 2;
	let R1 = r1 + r;
	let R2 = r2 + r;

	let dx = x2 - x1;
	let dy = y2 - y1;
	let d = sqrt(dx * dx + dy * dy);

	if (d > R1 + R2) {
		return;
	}

	let dirX = dx / d;
	let dirY = dy / d;

	let a = (R1 * R1 - R2 * R2 + d * d) / (2 * d);
	let underRoot = R1 * R1 - a * a;
	if (underRoot < 0) return;
	let h = sqrt(underRoot);


	let midX = x1 + dirX * a;
	let midY = y1 + dirY * a;

	let perpX = -dirY * h;
	let perpY = dirX * h;

	let cx1 = midX + perpX;
	let cy1 = midY + perpY;

	let cx2 = midX - perpX;
	let cy2 = midY - perpY;

	if (dist(cx1, cy1, cx2, cy2) < r * 2) {
		return;
	}

	let ang1 = atan2(y1 - cy1, x1 - cx1);
	let ang2 = atan2(y2 - cy1, x2 - cx1);
	let ang3 = atan2(y2 - cy2, x2 - cx2);
	let ang4 = atan2(y1 - cy2, x1 - cx2);

	if (ang2 < ang1) {
		ang2 += TAU;
	}
	beginShape();
	for (let i = ang1; i < ang2; i += TAU / 180) {
		vertex(cx1 + r * cos(i), cy1 + r * sin(i));
	}

	if (ang4 < ang3) {
		ang4 += TAU;
	}
	for (let i = ang3; i < ang4; i += TAU / 180) {
		vertex(cx2 + r * cos(i), cy2 + r * sin(i));
	}
	endShape();
}

function createGrid() {
	grid = [];
	let area = width * 0.8;
	let cellW = area / gridResolution;
	for (let i = 0; i < gridResolution; i++) {
		grid[i] = [];
		for (let j = 0; j < gridResolution; j++) {
			let cellX = i * cellW + (cellW / 2) + ((width - area) / 2);
			let cellY = j * cellW + (cellW / 2) + ((width - area) / 2);
			let colorIndex = int(random(palette.length));
			let cellSize = cellW * 0.725;

			if (i > 0) {
				let leftCell = grid[i - 1][j];
				while (colorIndex === leftCell.colorIndex) {
					colorIndex = int(random(palette.length));
				}
			}

			if (j > 0) {
				let aboveCell = grid[i][j - 1];
				while (colorIndex === aboveCell.colorIndex) {
					colorIndex = int(random(palette.length));
				}
			}

			grid[i][j] = { x: cellX, y: cellY, size: cellSize, colorIndex: colorIndex };
		}
	}
}

function drawConnections() {
	noStroke();
	for (let i = 0; i < gridResolution; i++) {
		for (let j = 0; j < gridResolution; j++) {
			let cell = grid[i][j];
			let col = palette[cell.colorIndex];
			fill(col);
			if ((i > 0) && (j > 0)) {
				let upLeft = grid[i - 1][j - 1];
				if (cell.colorIndex === upLeft.colorIndex) {
					let distance = dist(cell.x, cell.y, upLeft.x, upLeft.y);
					drawAetherLink(cell.x, cell.y, cell.size, upLeft.x, upLeft.y, upLeft.size, distance * 0.9);
				}
			}

			if ((i > 0) && (j < (gridResolution - 1))) {
				let downLeft = grid[i - 1][j + 1];
				if (cell.colorIndex === downLeft.colorIndex) {
					let distance = dist(cell.x, cell.y, downLeft.x, downLeft.y);
					drawAetherLink(cell.x, cell.y, cell.size, downLeft.x, downLeft.y, downLeft.size, distance * 0.9);
				}
			}
		}
	}
}

